def cf_to_fraction(a):
    # a is list of coefficients [a0, a1, ..., an]
    # compute continued fraction value
    # start from the end
    if not a:
        return Fraction(0)
    frac = Fraction(a[-1])
    for coeff in reversed(a[:-1]):
