def christoffel_word(p, q):
    # lower Christoffel word from (0,0) to (q,p)
    # using floor(i*p/q)
    word = []
    prev = 0
    for i in range(1, p+q):
        cur = (i * p) // q
        if cur == prev:
            word.append('x')
        else:
            word.append('y')
            prev = cur
    return ''.join(word)

