def sum_sq(n):
    # product_{i=0}^{n-1} (1 + x^{3^i} + x^{2*3^i} + x^{3*3^i})
    # compute coefficients via convolution
    coeffs = [1]
    for i in range(n):
        shift = 3**i
        new = [0]*(len(coeffs)+3*shift)
        for k, c in enumerate(coeffs):
            for d in range(4):
                new[k + d*shift] += c
        coeffs = new
    return sum(c*c for c in coeffs)

